-- The rows of a Ren store at migration 0007, recorded by
-- `write_the_newest_store_fixture` (tests/upgrade.rs). Frozen once
-- its migration is on main: today's store must open it.

PRAGMA blobs.page_size = 16384;
CREATE TABLE blobs.chunks (hash BLOB PRIMARY KEY, codec TEXT NOT NULL, raw_len INTEGER NOT NULL, data BLOB NOT NULL) WITHOUT ROWID;

